/**
 * A drawn nav icon, e.g. drawnIcon("plans").
 * @param {keyof typeof NAV_ART} name
 */
export function drawnIcon(name) {
  const icon = document.createElementNS(SVG, "svg");
  for (const [attr, value] of Object.entries({ viewBox: "0 0 24 24", "aria-hidden": "true", "stroke-linecap": "round", "stroke-linejoin": "round" })) icon.setAttribute(attr, value);
  for (const attrs of NAV_ART[name]) {
    const path = document.createElementNS(SVG, "path");
    for (const [attr, value] of Object.entries(attrs)) path.setAttribute(attr, String(value));
    icon.append(path);
  }
  return icon;
}

